class Solution {
public:
    vector<int> deckRevealedIncreasing(vector<int>& deck) {
        sort(deck.begin(), deck.end());
        int n = deck.size();
        queue<int> q;
        for (int i = 0; i < n; i++) q.push(i);
        vector<int> res(n);
        for (int k = 0; k < n; k++) {
            res[q.front()] = deck[k];
            q.pop();
            if (!q.empty()) {
                q.push(q.front());
                q.pop();
            }
        }
        return res;
    }
};
